test('every basemap host the browser must draw is allowed by the CSP img-src', async () => {
  // Regression: the OSM basemap shipped in `ae4da93` without a matching
  // `img-src` entry, so the browser blocked every tile (`browser-check.mjs`
  // stopped at “timeout waiting for map tiles (last: 0)”), and the whole
  // worldwide basemap was invisible in production. The CSP file is the only
  // place that can silently drop a host, so it is asserted here.
  const { readFile } = await import('node:fs/promises');
  const headers = await readFile(new URL('../public/_headers', import.meta.url), 'utf8');
  const csp = /Content-Security-Policy:([^\n]*)/.exec(headers);
  assert.ok(csp, 'public/_headers declares a Content-Security-Policy');
  const directive = /(?:^|;)\s*img-src([^;]*)/.exec(csp[1]);
  assert.ok(directive, 'the CSP declares img-src');
  const allowed = directive[1].split(/\s+/).filter(Boolean);

  for (const layer of BASE_LAYERS) {
    const host = new URL(layer.urlTemplate.replace(/\{[^}]*\}/g, '0')).origin;
    assert.ok(
      allowed.includes(host),
      `img-src must allow ${host} (base layer “${layer.key}”); allowed: ${allowed.join(' ')}`,
    );
  }
  // The archival imagery needs the same treatment: a preview host that is not
  // in img-src renders as an empty viewer in the browser only.
  for (const host of ['https://www.e-rara.ch']) {
    assert.ok(allowed.includes(host), `img-src must allow the archival imagery host ${host}`);
  }
});

